mapper.select:
SELECT v.post_id, p.title AS post_title, SUM(v.view_count) AS view_count, 0.0 AS percent
FROM (
    SELECT post_id, view_count FROM post_view_country_daily_stat
    WHERE stat_date >= DATE(#{startTime})
      AND stat_date < DATE(DATE_ADD(#{endTime}, INTERVAL 1 SECOND))
      AND country = #{country}
    UNION ALL
    SELECT post_id, COUNT(*) AS view_count FROM post_view_log
    WHERE visited_at >= #{startTime} AND visited_at < DATE_ADD(#{endTime}, INTERVAL 1 SECOND)
      AND COALESCE(NULLIF(country, ''), '未知') = #{country}
    GROUP BY post_id
) v LEFT JOIN post p ON v.post_id = p.id
GROUP BY v.post_id, p.title ORDER BY view_count DESC LIMIT #{limit}
